import bisect

class Solution:
    def minAbsoluteSumDiff(self, nums1: list[int], nums2: list[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums1)
        sorted_nums1 = sorted(nums1)

        total = sum(abs(a - b) for a, b in zip(nums1, nums2))
        max_gain = 0

        for a, b in zip(nums1, nums2):
            orig_diff = abs(a - b)
            idx = bisect.bisect_left(sorted_nums1, b)
            if idx < n:
                max_gain = max(max_gain, orig_diff - abs(sorted_nums1[idx] - b))
            if idx > 0:
                max_gain = max(max_gain, orig_diff - abs(sorted_nums1[idx - 1] - b))

        return (total - max_gain) % MOD

class Solution {
public:
    int minAbsoluteSumDiff(vector<int>& nums1, vector<int>& nums2) {
        long long MOD = 1000000007;
        int n = nums1.size();
        vector<int> sorted1 = nums1;
        sort(sorted1.begin(), sorted1.end());

        long long total = 0;
        int maxGain = 0;
        for (int i = 0; i < n; ++i) {
            int origDiff = abs(nums1[i] - nums2[i]);
            total += origDiff;
            auto it = lower_bound(sorted1.begin(), sorted1.end(), nums2[i]);
            if (it != sorted1.end()) {
                maxGain = max(maxGain, origDiff - abs(*it - nums2[i]));
            }
            if (it != sorted1.begin()) {
                maxGain = max(maxGain, origDiff - abs(*prev(it) - nums2[i]));
            }
        }
        return (total - maxGain) % MOD;
    }
};

import java.util.*;

class Solution {
    public int minAbsoluteSumDiff(int[] nums1, int[] nums2) {
        long MOD = 1_000_000_007L;
        int n = nums1.length;
        int[] sorted1 = nums1.clone();
        Arrays.sort(sorted1);

        long total = 0;
        int maxGain = 0;
        for (int i = 0; i < n; ++i) {
            int origDiff = Math.abs(nums1[i] - nums2[i]);
            total += origDiff;
            int idx = Arrays.binarySearch(sorted1, nums2[i]);
            if (idx >= 0) {
                maxGain = Math.max(maxGain, origDiff);
            } else {
                int ins = -idx - 1;
                if (ins < n) {
                    maxGain = Math.max(maxGain, origDiff - Math.abs(sorted1[ins] - nums2[i]));
                }
                if (ins > 0) {
                    maxGain = Math.max(maxGain, origDiff - Math.abs(sorted1[ins - 1] - nums2[i]));
                }
            }
        }
        return (int)((total - maxGain) % MOD);
    }
}

