var minAbsoluteSumDiff = function(nums1, nums2) {
    const MOD = 1000000007n;
    const n = nums1.length;
    const sorted1 = [...nums1].sort((a, b) => a - b);

    const binarySearch = (target) => {
        let low = 0, high = n;
        while (low < high) {
            const mid = Math.floor((low + high) / 2);
            if (sorted1[mid] < target) low = mid + 1;
            else high = mid;
        }
        return low;
    };

    let total = 0n;
    let maxGain = 0;
    for (let i = 0; i < n; ++i) {
        const origDiff = Math.abs(nums1[i] - nums2[i]);
        total += BigInt(origDiff);
        const idx = binarySearch(nums2[i]);
        if (idx < n) {
            maxGain = Math.max(maxGain, origDiff - Math.abs(sorted1[idx] - nums2[i]));
        }
        if (idx > 0) {
            maxGain = Math.max(maxGain, origDiff - Math.abs(sorted1[idx - 1] - nums2[i]));
        }
    }
    return Number((total - BigInt(maxGain)) % MOD);
};
